solution:
type QuizQuestion {
  text: Str;
  correct_answer: Int;
  points: Int;
}

type QuizSession {
  questions: Vec[QuizQuestion];
  score: Int;
  correct: Int;
}

fn run_quiz(session: &mut QuizSession) {
  let mut i = 0;
  while i < session.questions.len() {
    let q = session.questions.get(i).unwrap();
    let answer = 0;
    if answer == q.correct_answer {
      session.score += q.points;
      session.correct += 1;
    };
    i += 1;
  };
}

fn get_grade(correct: Int, total: Int) -> Str {
  if total == 0 { return "F"; };
  let pct = correct * 100 / total;
  if pct >= 90 { return "A"; };
  if pct >= 80 { return "B"; };
  if pct >= 70 { return "C"; };
  if pct >= 60 { return "D"; };
  "F"
}

fn main() -> Int {
  let mut session = QuizSession{ questions: Vec[QuizQuestion].new(), score: 0, correct: 0 };
  session.questions.push(QuizQuestion{ text: "2+2?", correct_answer: 0, points: 10 });
  session.questions.push(QuizQuestion{ text: "Capital of France?", correct_answer: 1, points: 10 });
  run_quiz(&mut session);
  io.println(get_grade(session.correct, 2));
  return 0;
}
